/* 공장 복장·동작 벡터 v1.0 (fruitfly-lab-expressions specs/factory) — classifier: asst P11, sia P03, moa P05, robo P08, fly P04, doc P15 */
var FVIMG={};(function(){var D={"asst": "data:image/webp;base64,", "sia": "data:image/webp;base64,", "moa": "data:image/webp;base64,", "robo": "data:image/webp;base64,", "fly": "data:image/webp;base64,", "doc": "data:image/webp;base64,"};Object.keys(D).forEach(function(k){var im=new Image();im.src=D[k];FVIMG[k]=im;});})();
function FVdraw(g,who,t,x,y,h){var im=FVIMG[who];if(!im||!im.complete||!im.naturalWidth)return false;var hh=h*0.92,bob=Math.sin(t*2.2+x*0.05)*hh*0.012,w=hh*im.naturalWidth/im.naturalHeight;g.drawImage(im,x-w/2,y-hh+bob,w,hh);return true;}
